package edu.uiuc.cs427app.helper;

import android.content.Context;
import android.content.SharedPreferences;
import android.util.Log;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;

import edu.uiuc.cs427app.data.entity.Theme;

/**
 * Generates and caches default themes using LLM.
 * 
 * This class provides a compliant way to have fallback themes:
 * - All themes are generated by LLM (compliant with requirements)
 * - Themes are cached locally to provide instant fallback
 * - No hardcoded colors are used
 * 
 * Usage:
 * 1. Call initialize() on app startup to pre-generate default themes
 * 2. Use getDefaultTheme() when LLM fails to get a cached LLM-generated theme
 * 
 * @author CS427 Team 407
 */
public class DefaultThemeGenerator {

    private static final String TAG = "DefaultThemeGenerator";
    private static final String PREFS_NAME = "default_themes_cache";
    private static final String KEY_THEMES_CACHE = "themes_cache";
    
    private final Context context;
    private LLMHelper llmHelper;
    private final SharedPreferences prefs;
    private final Gson gson;
    
    // In-memory cache for instant access
    private Map<String, Theme> themeCache = new HashMap<>();
    
    // Theme descriptions that will be generated
    private static final String[] DEFAULT_THEME_DESCRIPTIONS = {
        "light",
        "dark",
        "blue"
    };
    
    /**
     * Constructor.
     * 
     * @param context Application context
     */
    public DefaultThemeGenerator(Context context) {
        this.context = context;
        this.prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
        this.gson = new Gson();
        
        // Load cached themes from SharedPreferences
        loadCachedThemes();
        
        // Create LLMHelper and set bidirectional reference
        this.llmHelper = new LLMHelper();
        this.llmHelper.setDefaultThemeGenerator(this);
    }
    
    /**
     * Set the LLMHelper instance (for use by MainActivity if needed).
     * 
     * @param llmHelper LLMHelper instance
     */
    public void setLLMHelper(LLMHelper llmHelper) {
        this.llmHelper = llmHelper;
        if (llmHelper != null) {
            llmHelper.setDefaultThemeGenerator(this);
        }
    }
    
    /**
     * Initialize default themes by generating them with LLM.
     * 
     * This should be called on app startup to pre-generate default themes.
     * Themes are cached locally for instant fallback.
     * 
     * @param callback Callback to notify when initialization completes
     */
    public void initialize(InitializationCallback callback) {
        Log.d(TAG, "Initializing default theme generation...");
        
        // Check if themes are already cached
        if (isThemesCached()) {
            Log.d(TAG, "Default themes already cached, skipping generation");
            if (callback != null) {
                callback.onInitializationComplete(true);
            }
            return;
        }
        
        // Generate themes using LLM
        generateDefaultThemes(0, callback);
    }
    
    /**
     * Generate all default themes sequentially.
     * 
     * @param index Current theme index
     * @param callback Callback to notify completion
     */
    private void generateDefaultThemes(int index, InitializationCallback callback) {
        if (index >= DEFAULT_THEME_DESCRIPTIONS.length) {
            // All themes generated
            saveCachedThemes();
            Log.d(TAG, "All default themes generated successfully");
            if (callback != null) {
                callback.onInitializationComplete(true);
            }
            return;
        }
        
        String description = DEFAULT_THEME_DESCRIPTIONS[index];
        Log.d(TAG, "Generating theme: " + description);
        
        llmHelper.generateTheme(description, new LLMHelper.ThemeCallback() {
            @Override
            public void onSuccess(Theme theme) {
                // Store theme in cache
                theme.setName(description);
                themeCache.put(description, theme);
                Log.d(TAG, "Successfully generated theme: " + description);
                
                // Generate next theme
                generateDefaultThemes(index + 1, callback);
            }
            
            @Override
            public void onError(String errorMessage) {
                Log.e(TAG, "Failed to generate theme '" + description + "': " + errorMessage);
                
                // Continue with next theme even if this one fails
                // At least we'll have some themes cached
                generateDefaultThemes(index + 1, callback);
            }
        });
    }
    
    /**
     * Get a default theme by description.
     * 
     * Returns a cached LLM-generated theme, ensuring full compliance
     * (no hardcoded colors).
     * 
     * @param description Theme description ("light", "dark", "blue")
     * @return Cached theme or null if not available
     */
    public Theme getDefaultTheme(String description) {
        Theme theme = themeCache.get(description);
        
        if (theme != null) {
            Log.d(TAG, "Returning cached default theme: " + description);
            return theme;
        }
        
        Log.w(TAG, "No cached default theme found for: " + description);
        return null;
    }
    
    /**
     * Get the LLMHelper instance.
     * 
     * @return LLMHelper instance
     */
    public LLMHelper getLLMHelper() {
        return llmHelper;
    }
    
    /**
     * Check if themes are already cached.
     * 
     * @return true if themes are cached, false otherwise
     */
    public boolean isThemesCached() {
        return !themeCache.isEmpty();
    }
    
    /**
     * Load cached themes from SharedPreferences.
     */
    private void loadCachedThemes() {
        String json = prefs.getString(KEY_THEMES_CACHE, null);
        if (json == null) {
            return;
        }
        
        try {
            Type type = new TypeToken<Map<String, Theme>>(){}.getType();
            themeCache = gson.fromJson(json, type);
            Log.d(TAG, "Loaded " + themeCache.size() + " cached themes");
        } catch (Exception e) {
            Log.e(TAG, "Failed to load cached themes: " + e.getMessage());
            themeCache.clear();
        }
    }
    
    /**
     * Save cached themes to SharedPreferences.
     */
    private void saveCachedThemes() {
        try {
            String json = gson.toJson(themeCache);
            prefs.edit()
                .putString(KEY_THEMES_CACHE, json)
                .apply();
            Log.d(TAG, "Saved " + themeCache.size() + " themes to cache");
        } catch (Exception e) {
            Log.e(TAG, "Failed to save themes to cache: " + e.getMessage());
        }
    }
    
    /**
     * Clear cached themes (forces regeneration on next initialization).
     */
    public void clearCache() {
        themeCache.clear();
        prefs.edit()
            .remove(KEY_THEMES_CACHE)
            .apply();
        Log.d(TAG, "Cleared theme cache");
    }
    
    /**
     * Callback interface for theme initialization.
     *
     * This interface is used to notify when default theme initialization
     * completes, allowing the caller to handle success or failure cases.
     */
    public interface InitializationCallback {
        /**
         * Called when default theme initialization completes.
         *
         * @param success True if initialization succeeded, false otherwise
         */
        void onInitializationComplete(boolean success);
    }
}

